void print_reversed(const char* s) {
    /* TODO: print the characters of s in reverse order */
}

int main(void) {
    char* s = NULL;
    size_t cap = 0;
    ssize_t len = getline(&s, &cap, stdin);
    if (len < 0) {
        s = (char*)calloc(1, 1);
        len = 0;
    }
    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r')) {
        s[--len] = '\0';
    }
    print_reversed(s);
    free(s);
    return 0;
}

